// Mounts a vendored html-in-canvas.dev demo inside our page chrome.
//
// The demo's parsed parts are inlined into the wrapper page (generated by
// scripts/build-embeds.mjs):
//   <script type="text/plain"       id="demo-styles">  …the demo's CSS…
//   <template                       id="demo-body">    …body markup, scripts stripped…
//   <script type="application/json" id="demo-scripts"> [{src,type,body}, …]
//
// We mount styles + body into a shadow root on #demo-host (so the demo's
// page-level CSS — `body, :host`, `*`, element selectors — can't touch our
// chrome), expose that ShadowRoot as window.__demoRoot (every demo resolves
// its elements via `window.__demoRoot ?? document`), then re-materialize the
// scripts so they actually run. Finally we build the Source/Accessibility
// code pane with the shared helpers from code-pane.js.
(() => {
  const host = document.getElementById('demo-host');
  if (!host) return;

  const stylesEl = document.getElementById('demo-styles');
  const bodyTpl = document.getElementById('demo-body');
  const scriptsEl = document.getElementById('demo-scripts');

  const styles = stylesEl ? stylesEl.textContent : '';
  const bodyHTML = bodyTpl ? bodyTpl.innerHTML.trim() : '';
  let scripts = [];
  try { scripts = JSON.parse(scriptsEl ? scriptsEl.textContent : '[]'); }
  catch (e) { console.error('[demo-embed] could not parse demo-scripts', e); }

  // Style-isolated mount.
  const shadow = host.attachShadow({ mode: 'open' });
  if (styles) {
    const st = document.createElement('style');
    st.textContent = styles;
    shadow.appendChild(st);
  }
  if (bodyTpl) shadow.appendChild(bodyTpl.content.cloneNode(true));

  // Demos look here first for their root (ShadowRoot supports getElementById).
  window.__demoRoot = shadow;

  // Run the demo's scripts in document order, awaiting external loads so a
  // library (e.g. Three.js) is ready before the inline script that uses it.
  (async () => {
    for (const s of scripts) {
      await new Promise((resolve) => {
        const node = document.createElement('script');
        if (s.type) node.type = s.type;
        if (s.src) {
          node.src = s.src;
          node.onload = node.onerror = () => resolve();
          document.body.appendChild(node);
        } else {
          node.textContent = s.body || '';
          document.body.appendChild(node);
          resolve();
        }
      });
    }
    buildPanel();
  })();

  function buildPanel() {
    const stage = host.closest('.stage');
    const CP = window.CodePane;
    if (!stage || !CP) return;

    document.body.setAttribute('data-wide', '');

    const wrap = document.createElement('section');
    wrap.className = 'demo-code';
    const left = document.createElement('div');
    stage.parentNode.insertBefore(wrap, stage);
    left.appendChild(stage);
    wrap.appendChild(left);

    const scriptSrc = scripts
      .map((s) => (s.src ? `// external library: ${s.src}` : (s.body || '').trim()))
      .filter(Boolean)
      .join('\n\n');

    wrap.appendChild(CP.buildPane({
      filename: location.pathname.split('/').pop() || '',
      sources: [
        { cap: 'The markup mounted in the canvas', code: bodyHTML, lang: 'html' },
        { cap: 'The styles', code: styles, lang: 'css' },
        { cap: 'The script that drives it', code: scriptSrc, lang: 'js' },
      ],
      a11yRoot: shadow,
    }));

    // The stage just changed width — let size-on-resize demos re-fit.
    window.dispatchEvent(new Event('resize'));
  }
})();
